        requires
            self.wf(),
            au.pred().args(self),
        ensures
            match out {
                Some(ret_au) => ret_au == au,
                None => au.resolves(),
            }
    {
        let tracked mut maybe_au = Some(au);
        let tracked mut auth_au: Option<GhostVarAuth<Option<FlipAU>>> = None;
        let res;

        open_atomic_invariant!(self.inv.borrow() => v => {
            let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
            res = self.pending.compare_exchange(Tracked(&mut pend_perm), 0, 1);

            proof {
                if res.is_ok() {
                    // Successfully transitioned from 0 to 1, extract the auth
                    let tracked mut gva = proto.take_empty();
                    // Update the ghost variable to store Some(au_to_move)
                    // Use gva (the GhostVarAuth we extracted) to update gv
                    let tracked au_to_move = maybe_au.tracked_take();
                    gva.update(&mut gv, Some(au_to_move));
                    // Store the gva for later use
                    auth_au = Some(gva);
                    proto = Offering(Tracked(au_to_move));
                }

                v = (value_perm, pend_perm, auth, gv, proto);
            }
        });

        if res.is_err() {
